#include "stdlib/lapack/base/dlassq.h"

/**
* Returns an updated sum of squares represented in scaled form.
*
* @param N        number of indexed elements
* @param X        input array
* @param incX     stride length for `X`
* @param scale    scaling factor
* @param sumsq    basic sum of squares from which output is factored out
*/
void API_SUFFIX(c_dlassq)( const LAPACK_INT N, const double *X, const LAPACK_INT incX, double *scale, double *sumsq ) {
	LAPACK_INT ox = 0;
	if ( incX < 0 ) {
		ox = ( 1 - N ) * incX;
	}
	API_SUFFIX(c_dlassq_ndarray)( N, X, incX, ox, scale, sumsq );
}
